// Só confirma que algo foi exibido quando o elemento existe e ocupa espaço na tela.
function waitShown(selector:string,timeout=5000){return new Promise<boolean>(resolve=>{const start=Date.now();const check=()=>{const el=document.querySelector<HTMLElement>(selector);if(el&&el.getClientRects().length){resolve(true);return;}if(Date.now()-start>timeout){resolve(false);return;}setTimeout(check,80);};check();});}
// @response: identifies an existing response window; no report is moved or recreated.
const RESPONSE_LOCATION='@response:';
const panelSelector=(key:string)=>key.startsWith(RESPONSE_LOCATION)?`[data-report-key="${CSS.escape(key.slice(RESPONSE_LOCATION.length))}"]`:`[data-home-panel="${CSS.escape(key)}"]`;
const panelReadySelector=(key:string)=>key.startsWith(RESPONSE_LOCATION)?panelSelector(key):`${panelSelector(key)} [data-ready]`;
function focusPanel(key:string,attempt=0){const el=document.querySelector<HTMLElement>(panelSelector(key));if(!el){if(attempt<12)setTimeout(()=>focusPanel(key,attempt+1),100);return;}el.scrollIntoView({behavior:'smooth',block:'nearest'});if(!el.hasAttribute('tabindex'))el.setAttribute('tabindex','-1');el.focus({preventScroll:true});}
// Validação e migração únicas para boot e recarga: a home é o padrão; startView 'last' devolve a visão salva.
function prepareWorkspace(data:Workspace,list:Project[],keepView?:'home'|'project'){
  const ids=new Set(list.map(p=>p.id));const {ws:merged,overflow,invalid}=normalizeHome({...defaultWorkspace,...data});
  merged.openProjects=(Array.isArray(merged.openProjects)?merged.openProjects:[]).filter(id=>ids.has(id));
  const saved=ids.has(merged.activeProject||'')?merged.activeProject:null;
  const view=keepView||(merged.startView==='last'?merged.view:'home')||'home';
  merged.view=view;merged.activeProject=view==='project'?saved||list[0]?.id||null:saved;
  if(merged.activeProject&&!merged.openProjects.includes(merged.activeProject))merged.openProjects.unshift(merged.activeProject);
  merged.compareProject=ids.has(merged.compareProject||'')?merged.compareProject:null;
  return {ws:merged,overflow,invalid};
}

function IconButton({icon:Icon,label,onClick,className='',disabled=false,children}:{icon:LucideIcon;label:string;onClick?:()=>void;className?:string;disabled?:boolean;children?:ReactNode}){return <button className={`icon-button ${className}`} title={label} aria-label={label} onClick={onClick} disabled={disabled}><Icon size={18}/>{children}</button>;}
function Empty({icon:Icon=Layers,title,children}:{icon?:LucideIcon;title:string;children?:ReactNode}){return <div className="empty-state"><div className="empty-orbit"><Icon size={26}/></div><strong>{title}</strong>{children&&<p>{children}</p>}</div>;}
function Modal({title,children,onClose,wide=false}:{title:string;children:ReactNode;onClose:()=>void;wide?:boolean}){
  const ref=useRef<HTMLDivElement>(null);const lastFocus=useRef<HTMLElement|null>(document.activeElement as HTMLElement);
  useEffect(()=>{const previous=document.body.style.overflow;document.body.style.overflow='hidden';const first=ref.current?.querySelector<HTMLElement>('input,textarea,select')||ref.current?.querySelector<HTMLElement>('button,[tabindex="0"]');first?.focus();const handler=(e:KeyboardEvent)=>{if(e.key==='Escape'){e.preventDefault();onClose();}if(e.key==='Tab'){const nodes=Array.from(ref.current?.querySelectorAll<HTMLElement>('button:not([disabled]),input:not([disabled]),textarea:not([disabled]),select:not([disabled]),a[href],[tabindex="0"]')||[]).filter(el=>el.offsetParent!==null);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}};document.addEventListener('keydown',handler);return()=>{document.body.style.overflow=previous;document.removeEventListener('keydown',handler);if(lastFocus.current?.isConnected)lastFocus.current.focus();};},[]);
  return <div className="modal-shade" onMouseDown={e=>{if(e.target===e.currentTarget){e.preventDefault();onClose();}}}><div ref={ref} className={`modal ${wide?'modal-wide':''}`} role="dialog" aria-modal="true" aria-label={title}><header><div><span className="eyebrow">MEGABRAIN</span><h2>{title}</h2></div><IconButton icon={X} label="Fechar janela" onClick={onClose}/></header>{children}</div></div>;
}

function Login({onConnected}:{onConnected:()=>void}){
  const [code,setCode]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('');
  async function connect(value=code){if(!value.trim()||busy)return;setBusy(true);setError('');try{await pair(value.trim());setCode('');onConnected();}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
  return <main className="login-page"><div className="login-brand"><img src={brain} alt=""/><span>MegaBrain<span className="brand-dot">.</span></span></div><div className="login-grid"><section className="login-story"><span className="eyebrow"><Circle size={9} fill="currentColor"/> SEU ESPAÇO DE TRABALHO</span><h1>Suas ideias.<br/>Todas na<br/><span>mesma mesa.</span></h1><p>Projetos, referências e resultados.<br/>Um lugar para acompanhar e continuar.</p><div className="login-pills"><span><Layers size={16}/> Tudo junto</span><span><Columns2 size={16}/> Lado a lado</span><span><Smartphone size={16}/> Onde você estiver</span></div></section><section className="pair-card"><div className="pair-art"><img src={brain} alt="Cérebro rosa do MegaBrain"/><span className="art-orbit orbit-one"/><span className="art-orbit orbit-two"/></div><div className="pair-content"><span className="eyebrow"><ShieldCheck size={14}/> CONEXÃO PRIVADA</span><h2>Conectar ao meu MegaBrain</h2><p>Use o código de conexão exibido no aplicativo do seu computador.</p><form onSubmit={e=>{e.preventDefault();void connect();}}><label htmlFor="pair-code">Código de conexão</label><input id="pair-code" value={code} onChange={e=>setCode(e.target.value)} placeholder="Cole seu código aqui" autoComplete="off" spellCheck={false}/>{error&&<p className="error-message" role="alert"><CircleAlert size={16}/>{error}</p>}<button className="primary full" disabled={busy||!code.trim()}>{busy?<LoaderCircle className="spin" size={18}/>:<ArrowRight size={18}/>} {busy?'Conectando…':'Entrar na minha mesa'}</button></form><div className="privacy-note"><ShieldCheck size={15}/><span>Seus projetos só aparecem depois da conexão.</span></div></div></section></div></main>;
}

type Context = {pid:string;target:string;label:string;anchor:{x:number;y:number};x:number;y:number};
function PreviewContent({item}:{item:Preview}){
  const url=safeUrl(item.url);if(!url)return <Empty icon={CircleAlert} title="Endereço indisponível">Este arquivo não tem um endereço válido.</Empty>;
  if(item.type==='image'||/\.(png|jpe?g|gif|webp|svg)(?:\?|$)/i.test(url))return <div className="preview-image"><img src={url} alt={item.title}/></div>;
  if(item.type==='audio')return <audio className="preview-audio" src={url} controls/>;
  if(item.type==='video')return <video className="preview-video" src={url} controls/>;
  if(isLocalPdfPreview(item.type,url,window.location.origin))return <iframe className="preview-frame preview-pdf" title={item.title} src={url} referrerPolicy="no-referrer"/>;
  if(item.type==='link')return <Empty icon={ExternalLink} title="Referência externa"><a href={url} target="_blank" rel="noopener noreferrer">Abrir a fonte <ArrowUpRight size={14}/></a></Empty>;
  if(/^\/api\/files\/[a-f0-9]{20}$/.test(new URL(url,window.location.origin).pathname)&&new URL(url,window.location.origin).origin===window.location.origin&&item.type==='html')return <ReportFrame fid={item.id} title={item.title} projectId={item.project_id}/>;
  return <><p className="preview-static-notice">Prévia estática e segura. Os scripts, respostas e ferramentas internas deste relatório não executam aqui. As ferramentas da mesa funcionam fora da prévia.</p><iframe className="preview-frame" title={item.title} src={url} sandbox={previewSandbox(url)} referrerPolicy="no-referrer"/></>;
}

function ProjectBoard({detail,jobs,ws,updateWorkspace,openPreview,onContext,onError,onSaved,onReload,onStartJob,onCancelJob,onReference,compare=false}:{detail:ProjectDetail;jobs:Job[];ws:Workspace;updateWorkspace:(fn:(w:Workspace)=>Workspace)=>void;openPreview:(p:Preview,compare?:boolean)=>void;onContext:(ctx:Context)=>void;onError:(e:unknown)=>void;onSaved:(m:string)=>void;onReload:()=>void;onStartJob:()=>void;onCancelJob:(id:string)=>Promise<void>;onReference:()=>void;compare?:boolean}){
  const holder=useRef<HTMLDivElement>(null);const [width,setWidth]=useState(0);const [organize,setOrganize]=useState(false);const [menu,setMenu]=useState(false);const hold=useRef<{timer:ReturnType<typeof setTimeout>;x:number;y:number}|null>(null);const suppressClick=useRef(false);
  const pid=detail.project.id;const narrow=width<560;const baseCols=narrow?1:width>=850?3:2;const cols=narrow?1:12;const unit=cols/baseCols;const oldKey=`${pid}:${narrow?'compact':baseCols===3?'desk':'wide'}`;const key=`${pid}:flex:${narrow?'compact':baseCols===3?'desk':'wide'}`;const hidden=ws.hiddenModules?.[pid]||[];const pins=(ws.views as DeskView[]).filter(v=>v.project_id===pid&&v.id&&v.url);const visible=[...MODULES.filter(m=>!hidden.includes(m.id)),...pins.map(v=>({id:'report:'+v.id,title:v.title,icon:FileImage,color:'pink'}))];
  const defaults:LayoutItem[]=visible.map((m,i)=>({i:m.id,x:narrow?0:(i%baseCols)*unit,y:narrow?i*4:Math.floor(i/baseCols)*4,w:unit,h:m.id==='now'?4:4,minW:1,minH:3,maxW:cols}));
  const saved=ws.layouts?.[key]||ws.layouts?.[oldKey]?.map(a=>({...a,x:a.x*unit,w:a.w*unit}));const layout=visible.map((m,i)=>{const a=saved?.find(a=>a.i===m.id);return a?{...a,w:Math.min(a.w,cols),x:Math.min(a.x,cols-Math.min(a.w,cols)),maxW:cols,minW:narrow?1:3,minH:3}:defaults[i];});
  useEffect(()=>{if(!holder.current)return;const ro=new ResizeObserver(entries=>setWidth(Math.floor(entries[0].contentRect.width)));ro.observe(holder.current);return()=>ro.disconnect();},[]);
  useEffect(()=>()=>{if(hold.current)clearTimeout(hold.current.timer);},[]);
  function saveLayout(next:readonly LayoutItem[]){updateWorkspace(w=>({...w,layouts:{...w.layouts,[key]:[...(w.layouts[key]||[]).filter(a=>hidden.includes(a.i)),...next.map(({i,x,y,w,h})=>({i,x,y,w,h}))]}}));}
  function adjust(id:string,dir:'up'|'down'|'wide'|'tall'|'small'){const next=layout.map(a=>({...a}));const item=next.find(a=>a.i===id)!;if(dir==='up'||dir==='down'){const sorted=[...next].sort((a,b)=>a.y-b.y||a.x-b.x);const idx=sorted.findIndex(a=>a.i===id);const peer=sorted[idx+(dir==='up'?-1:1)];if(peer){[item.x,peer.x]=[peer.x,item.x];[item.y,peer.y]=[peer.y,item.y];}}else if(dir==='wide'){item.w=item.w===cols?unit:cols;item.x=0;}else if(dir==='tall')item.h++;else item.h=Math.max(3,item.h-1);saveLayout(next);}
  function clearHold(){if(hold.current){clearTimeout(hold.current.timer);hold.current=null;}}
  function press(e:ReactPointerEvent,mod:string){if(window.brainCursorTools||organize||e.button!==0||(e.target as HTMLElement).closest('button:not([data-target]),a,input,textarea,select,summary,iframe,audio,video'))return;const rect=e.currentTarget.getBoundingClientRect();const target=(e.target as HTMLElement).closest<HTMLElement>('[data-target]');const ctx={pid,target:target?.dataset.target||`module:${mod}`,label:target?.dataset.label||visible.find(m=>m.id===mod)!.title,anchor:{x:(e.clientX-rect.left)/rect.width,y:(e.clientY-rect.top)/rect.height},x:e.clientX,y:e.clientY};clearHold();hold.current={timer:setTimeout(()=>{suppressClick.current=true;onContext(ctx);hold.current=null;},1000),x:e.clientX,y:e.clientY};}
  const assets=[...(detail.assets||[]),...(detail.references||[])].filter((a,i,arr)=>arr.findIndex(b=>b.id===a.id)===i);
  const ownJobs=jobs.filter(j=>j.project_id===pid&&!j.external_operation);
  const externalOperations=jobs.filter(j=>j.project_id===pid&&j.external_operation);
  function pin(item:Preview){updateWorkspace(w=>({...w,views:[...((w.views||[]) as DeskView[]).filter(v=>!(v.project_id===pid&&v.id===item.id)),{...item,project_id:pid}]}));}
  function unpin(id:string){updateWorkspace(w=>({...w,views:((w.views||[]) as DeskView[]).filter(v=>!(v.project_id===pid&&'report:'+v.id===id))}));}
  function drop(e:React.DragEvent){e.preventDefault();const rect=holder.current?.getBoundingClientRect();if(!rect)return;const x=Math.max(0,Math.min(cols-1,Math.floor((e.clientX-rect.left)/rect.width*cols)));const y=Math.max(0,Math.floor((e.clientY-rect.top)/92));const mod=e.dataTransfer.getData('application/x-megabrain-module');if(MODULES.some(m=>m.id===mod)){updateWorkspace(w=>({...w,hiddenModules:{...w.hiddenModules,[pid]:hidden.filter(id=>id!==mod)},layouts:{...w.layouts,[key]:[...layout.filter(a=>a.i!==mod),{i:mod,x,y,w:unit,h:4}]}}));return;}try{const data=JSON.parse(e.dataTransfer.getData(DRAG_REPORT));if(data.pid!==pid)return;const item=libraryItems(detail).find(v=>v.id===data.id);if(item){pin(item);updateWorkspace(w=>({...w,layouts:{...w.layouts,[key]:[...layout.filter(a=>a.i!=='report:'+item.id),{i:'report:'+item.id,x:Math.min(x,Math.max(0,cols-unit*2)),y,w:Math.min(unit*2,cols),h:5}]}}));}}catch{}}
  function renderModule(id:string):ReactNode{
    if(id.startsWith('report:')){const item=pins.find(v=>'report:'+v.id===id);return item?<PreviewContent item={item}/>:null;}
    if(id==='now')return <div className="now-content"><FeedbackReceipt comments={detail.comments||[]}/><div className="now-kicker"><span className="small-tag pink"><Sparkles size={12}/> Na sua mesa</span><span className="source-badge"><Folder size={12}/> Fonte local</span></div><h2>{detail.project.summary?concise(detail.project.summary):'Resumo ainda não registrado.'}</h2>{detail.project.summary&&detail.project.summary.length>170&&<details className="summary-detail"><summary>Ver contexto completo <ChevronDown size={13}/></summary><p>{detail.project.summary}</p></details>}<p className="next-step">{detail.project.next_step?concise(detail.project.next_step,150):'Próximo passo ainda não registrado na fonte.'}</p><div className="now-actions"><button className="primary" onClick={onStartJob}><Plus size={17}/>Novo pedido<ArrowUpRight size={16}/></button><button className="text-button" onClick={()=>document.getElementById(`${pid}-results`)?.scrollIntoView({behavior:'smooth',block:'nearest'})}>Ver resultados <ArrowRight size={15}/></button></div><div className="now-source"><Clock3 size={14}/><span>{dateText(detail.project.updated_at)}<small>{detail.project.source||'Última atualização registrada no projeto'}</small></span></div></div>;
    if(id==='results')return detail.deliveries?.length?<div className="delivery-list">{detail.deliveries.map((d,i)=><article className="delivery" key={d.id} data-target={d.file_id?`file:${d.file_id}`:`delivery:${d.id}`} data-label={d.title}><div className={`file-tile ${d.type==='html'?'pink':'green'}`}>{d.type==='image'?<FileImage size={23}/>:<Layers size={23}/>}</div><div className="delivery-body"><div className="row-line"><span className="micro-label">{d.type?.toUpperCase()||'ENTREGA'}</span>{i===0&&<span className="new-tag">Mais recente</span>}</div><h3>{d.title}</h3>{d.summary&&<p>{d.summary}</p>}<div className="delivery-meta"><span><Circle size={7} fill="currentColor"/>{d.status||'Status não registrado'}</span><time>{dateText(d.updated_at)}</time></div><span className="proof-label"><File size={12}/> {d.verification_label||'Verificação não registrada'}</span></div><IconButton icon={ArrowUpRight} label={`Abrir ${d.title}`} disabled={!d.file_id} onClick={()=>d.file_id&&openPreview({id:d.file_id,title:d.title,type:d.type||'html',url:fileUrl(d.file_id),caption:d.session||'Entrega do projeto'})}/></article>)}</div>:<Empty title="Os resultados chegam aqui">As entregas encontradas no projeto aparecem com origem e data.</Empty>;
    if(id==='references')return <><div className="module-intro"><p>O repertório perto do resultado.</p><button className="text-button" onClick={onReference}><Plus size={15}/>Adicionar link</button></div>{assets.length?<div className="asset-grid">{assets.map(a=>{const image=a.type==='image';const url=safeUrl(a.url)||fileUrl(a.id);return <button className="asset" data-target={`file:${a.id}`} data-label={a.name||a.title||'Referência'} key={a.id} onClick={()=>openPreview({id:a.id,title:a.name||a.title||'Referência',type:a.type||'link',url,caption:a.role==='reference'?'Referência do projeto':a.role||'Arquivo do projeto'})}><div className={`asset-art ${image?'':'asset-link'}`}>{image?<img src={url} alt="" loading="lazy"/>:<><Link size={28}/><span>REFERÊNCIA</span></>}</div><span>{a.name||a.title||'Referência'}</span><small><ExternalLink size={11}/>{image?'Abrir imagem':'Abrir referência'}</small></button>;})}</div>:<Empty icon={Image} title="Espaço para suas referências">Adicione um link. Os arquivos indexados também ficam disponíveis aqui.</Empty>}</>;
    if(id==='activity')return <div className="activity-list">{ownJobs.map(j=><ExecutionCard key={j.id} job={j} onPreview={openPreview} onCancel={onCancelJob}/>)}{(detail.activity||[]).slice(0,12).map(a=><div className="timeline-row" key={a.id}><span className="timeline-dot"/><div><strong>{a.title}</strong>{a.detail&&<p>{a.detail}</p>}<small>{dateText(a.at)}</small></div></div>)}{detail.sessions?.length>0&&<details className="observed-sessions"><summary><Activity size={14}/>Sessões observadas <span>{detail.sessions.length}</span><ChevronDown size={14}/></summary>{detail.sessions.map(s=><div key={s.id}><strong>{s.vendor} · {s.title}</strong><p>{s.status}</p><small>{s.evidence||'Fonte local; não confirma execução em andamento.'}</small></div>)}</details>}{!ownJobs.length&&!detail.activity?.length&&!detail.sessions?.length&&<Empty icon={Activity} title="Nenhuma atividade registrada">As atualizações reais do projeto aparecerão aqui.</Empty>}</div>;
    return <RoutingEditor pid={pid} onError={onError} onSaved={onSaved}/>;
  }
  return <section data-cf-project={pid} data-cf-ignorar={organize?'':undefined} className={`project-board ${compare?'compare-board':''}`} aria-label={`Projeto ${detail.project.name}`}><div className="project-board-head"><div className="project-heading"><span className="project-swatch" style={{background:detail.project.color||'#ff82c4'}}/><h2>{detail.project.name}</h2></div><div className="board-tools"><button className={`text-button ${organize?'selected':''}`} onClick={()=>setOrganize(!organize)}><Settings2 size={15}/>{organize?'Concluir organização':'Organizar'}</button><div className="popover-wrap"><IconButton icon={MoreHorizontal} label={`Módulos de ${detail.project.name}`} onClick={()=>setMenu(!menu)}/>{menu&&<div className="small-popover"><strong>O que fica na mesa</strong>{MODULES.map(m=><label key={m.id}><input type="checkbox" checked={!hidden.includes(m.id)} onChange={e=>updateWorkspace(w=>({...w,hiddenModules:{...w.hiddenModules,[pid]:e.target.checked?hidden.filter(id=>id!==m.id):[...hidden,m.id]}}))}/><m.icon size={15}/>{m.title}</label>)}<button onClick={()=>{updateWorkspace(w=>({...w,layouts:Object.fromEntries(Object.entries(w.layouts).filter(([k])=>!k.startsWith(`${pid}:`))),hiddenModules:{...w.hiddenModules,[pid]:[]}}));setMenu(false);}}><RefreshCw size={14}/>Restaurar organização</button><button onClick={()=>{onReload();setMenu(false);}}><RefreshCw size={14}/>Atualizar dados</button></div>}</div></div></div>{organize&&<div className="organize-notice"><Grip size={16}/><span>Arraste pelo título ou use os botões para mover e mudar o tamanho. A mesa salva sozinha.</span></div>}{externalOperations.map(job=><ExternalOperation key={job.id} operation={job.external_operation!} assets={detail.assets||[]} onPreview={openPreview}/>)}<nav className="module-shortcuts" aria-label="Acesso aos módulos">{MODULES.slice(0,3).map(m=><button key={m.id} draggable onDragStart={e=>{e.dataTransfer.setData('application/x-megabrain-module',m.id);e.dataTransfer.effectAllowed='copy';}} onClick={()=>{if(hidden.includes(m.id))updateWorkspace(w=>({...w,hiddenModules:{...w.hiddenModules,[pid]:hidden.filter(id=>id!==m.id)}}));document.getElementById(`${pid}-${m.id}`)?.scrollIntoView({behavior:'smooth',block:'nearest'});}}><m.icon size={16}/>{m.title}</button>)}</nav><div className="report-desk"><div className="grid-holder" ref={holder} onDragOver={e=>{if(Array.from(e.dataTransfer.types).some(t=>t===DRAG_REPORT||t==='application/x-megabrain-module'))e.preventDefault();}} onDrop={drop}>{width>0&&<GridLayout width={width} cols={cols} rowHeight={76} margin={[16*workspacePreferences(ws).spacing/100,16*workspacePreferences(ws).spacing/100]} containerPadding={[0,0]} layout={layout} isDraggable={!narrow} isResizable={!narrow} draggableHandle=".module-head" draggableCancel="button,input,textarea,iframe" compactType="vertical" preventCollision={false} onDragStop={next=>saveLayout(next)} onResizeStop={next=>saveLayout(next)}>{visible.map(mod=><div data-cf-module={mod.id} data-cf-ancora={`${pid}:module:${mod.id}`} className={`module-card accent-${mod.color} ${mod.id.startsWith('report:')?'pinned-report':''}`} key={mod.id} id={`${pid}-${mod.id}`} onClickCapture={e=>{if(suppressClick.current){e.preventDefault();e.stopPropagation();suppressClick.current=false;}}} onContextMenu={e=>{if(suppressClick.current)e.preventDefault();}} onPointerDown={e=>press(e,mod.id)} onPointerUp={clearHold} onPointerCancel={clearHold} onPointerMove={e=>{if(hold.current&&Math.hypot(e.clientX-hold.current.x,e.clientY-hold.current.y)>8)clearHold();}}><header className={`module-head ${organize?'module-handle':''}`}><div><span className="module-icon"><mod.icon size={17}/></span><h3>{mod.title}</h3>{mod.id==='results'&&detail.deliveries.length>0&&<span className="module-count">{detail.deliveries.length}</span>}</div><div>{mod.id.startsWith('report:')&&<IconButton icon={X} label={`Retirar ${mod.title} da mesa`} onClick={()=>unpin(mod.id)}/>} {organize?<Grip size={17}/>:<IconButton icon={MoreHorizontal} label={`Ações de ${mod.title}`} onClick={()=>onContext({pid,target:`module:${mod.id}`,label:mod.title,anchor:{x:.5,y:.1},x:Math.min(window.innerWidth-280,window.innerWidth/2),y:170})}/>}</div></header>{organize&&<div className="organize-controls"><IconButton icon={ArrowUp} label={`Mover ${mod.title} para cima`} onClick={()=>adjust(mod.id,'up')}/><IconButton icon={ArrowDown} label={`Mover ${mod.title} para baixo`} onClick={()=>adjust(mod.id,'down')}/>{!narrow&&<IconButton icon={Columns2} label={`Alternar largura de ${mod.title}`} onClick={()=>adjust(mod.id,'wide')}/>}<IconButton icon={Plus} label={`Aumentar altura de ${mod.title}`} onClick={()=>adjust(mod.id,'tall')}/><IconButton icon={Minus} label={`Diminuir altura de ${mod.title}`} onClick={()=>adjust(mod.id,'small')}/></div>}<div className="module-body">{renderModule(mod.id)}</div></div>)}</GridLayout>}</div><ReportLibrary detail={detail} onPin={pin} onOpen={openPreview}/></div>{visible.length===0&&<Empty icon={LayoutDashboard} title="Sua mesa está livre"><button className="text-button" onClick={()=>updateWorkspace(w=>({...w,hiddenModules:{...w.hiddenModules,[pid]:[]}}))}>Restaurar os módulos</button></Empty>}</section>;
}

export default function App(){
  const [authenticated,setAuthenticated]=useState<boolean|null>(null);const [projects,setProjects]=useState<Project[]>([]);const [details,setDetails]=useState<Record<string,ProjectDetail>>({});const [workspace,setWorkspace]=useState<Versioned<Workspace>>({revision:0,data:defaultWorkspace});const [ready,setReady]=useState(false);const [jobs,setJobs]=useState<Job[]>([]);const [online,setOnline]=useState(true);const [lastSync,setLastSync]=useState('');const [toast,setToast]=useState('');const [search,setSearch]=useState(false);const [query,setQuery]=useState('');const [guide,setGuide]=useState<Guide|null>(null);const [guideOpen,setGuideOpen]=useState(false);const [connection,setConnection]=useState<null|{remote_url:string|null;status:string;computer_required:boolean;pair_url:string|null;qr_url:string|null;platform:string}>(null);const [connectionOpen,setConnectionOpen]=useState(false);const [context,setContext]=useState<Context|null>(null);const [comment,setComment]=useState<Context|null>(null);const [commentText,setCommentText]=useState('');const [commentBusy,setCommentBusy]=useState(false);const [referenceProject,setReferenceProject]=useState<string|null>(null);const [referenceUrl,setReferenceUrl]=useState('');const [referenceTitle,setReferenceTitle]=useState('');const [referenceBusy,setReferenceBusy]=useState(false);const [jobProject,setJobProject]=useState<string|null>(null);const [previews,setPreviews]=useState<Preview[]>([]);const [previewPicker,setPreviewPicker]=useState(false);const [comparePicker,setComparePicker]=useState(false);const [dirty,setDirty]=useState(false);const [saving,setSaving]=useState(false);const [conflict,setConflict]=useState(false);const [savePaused,setSavePaused]=useState(false);const [loadError,setLoadError]=useState('');const [newEvents,setNewEvents]=useState(0);const [quotasOpen,setQuotasOpen]=useState(false);const [settingsOpen,setSettingsOpen]=useState(false);const [responsesVisible,setResponsesVisible]=useState(true);const [jobPicker,setJobPicker]=useState(false);const [returnFeed,setReturnFeed]=useState<ReturnFeed|null>(null);const [returnError,setReturnError]=useState('');const [returnRefresh,setReturnRefresh]=useState(0);
  const commentRequest=useRef<MutationAttempt|null>(null);const referenceRequest=useRef<MutationAttempt|null>(null);const commentDrafts=useRef<Record<string,string>>({});const workspaceRef=useRef(workspace);const savedBase=useRef<Workspace>(defaultWorkspace);const editSerial=useRef(0);const eventCursor=useRef(0);const savingRef=useRef(false);const initialized=useRef(false);const catalogRef=useRef<{projects:Project[];jobs:Job[];details:Record<string,ProjectDetail>}>({projects:[],jobs:[],details:{}});const ws=workspace.data;const prefs=workspacePreferences(ws);const sidebar=prefs.mode!=='hidden';const homeView=ws.view!=='project';
  const setSidebar=(show:boolean)=>updateWorkspace(w=>({...w,railMode:show?(w.lastRailMode==='icons'?'icons':'expanded'):'hidden',lastRailMode:show?w.lastRailMode:workspacePreferences(w).mode}));
  useEffect(()=>{document.documentElement.dataset.mbTheme=prefs.theme;},[prefs.theme]);
  useEffect(()=>{workspaceRef.current=workspace;},[workspace]);
  useEffect(()=>{catalogRef.current={projects,jobs,details};},[projects,jobs,details]);
  const notify=useCallback((message:string)=>setToast(message),[]);
  const onError=useCallback((e:unknown)=>{if(e instanceof ApiError&&e.status===401){setAuthenticated(false);setReady(false);initialized.current=false;}else notify((e as Error).message||'Não foi possível concluir.');},[notify]);
  const loadDetail=useCallback(async(id:string)=>{const value=await api<ProjectDetail>(`/projects/${id}`);const detail={...value,deliveries:value.deliveries||[],assets:value.assets||[],activity:value.activity||[],sessions:value.sessions||[],comments:value.comments||[]};setDetails(prev=>({...prev,[id]:detail}));return detail;},[]);
  function restoreNotice(overflow:number,invalid:number){if(overflow||invalid)notify([overflow?`${overflow} painéis acima do limite de ${HOME_PANEL_LIMIT} não foram restaurados.`:'',invalid?`${invalid} painéis salvos estavam inválidos e foram ignorados.`:''].filter(Boolean).join(' '));}
  async function boot(){setLoadError('');try{const [p,w,j]=await Promise.all([api<{projects:Project[];scanned_at?:string}>('/projects'),api<Versioned<Workspace>>('/workspace'),api<{jobs:Job[]}>('/jobs')]);setProjects(p.projects);const {ws:merged,overflow,invalid}=prepareWorkspace(w.data,p.projects);setWorkspace({...w,data:merged});setResponsesVisible(merged.responsesCollapsed!==true);restoreNotice(overflow,invalid);setPreviews(Array.isArray(merged.responseViews)?(merged.responseViews as Preview[]).filter(p=>p&&typeof p.id==='string'&&typeof p.url==='string'&&typeof p.title==='string'&&safeUrl(p.url)):[]);workspaceRef.current={...w,data:merged};savedBase.current=merged;setJobs(j.jobs);setLastSync(p.scanned_at||'');setReady(true);setOnline(true);setDirty(false);setSavePaused(false);initialized.current=true;}catch(e){onError(e);setLoadError((e as Error).message);}}
  useEffect(()=>{let active=true;let attempt=0;const connect=()=>{const current=++attempt;const fragment=new URLSearchParams(window.location.hash.slice(1));const code=fragment.get('pair');if(code)window.history.replaceState(null,'',window.location.pathname+window.location.search);const connecting=code?pair(code):session();connecting.then(()=>{if(active&&current===attempt)setAuthenticated(true);}).catch(()=>{if(active&&current===attempt)setAuthenticated(false);});};connect();window.addEventListener('hashchange',connect);return()=>{active=false;window.removeEventListener('hashchange',connect);};},[]);
  useEffect(()=>{if(authenticated&&!initialized.current)void boot();},[authenticated]);
  useEffect(()=>{if(!authenticated||!ready)return;for(const id of [ws.activeProject,ws.compareProject].filter(Boolean) as string[])void loadDetail(id).catch(onError);},[authenticated,ready,ws.activeProject,ws.compareProject,loadDetail,onError]);
  useEffect(()=>{if(!authenticated||!ready)return;let active=true;let timer:ReturnType<typeof setTimeout>;const poll=async()=>{try{const [e,j]=await Promise.all([api<{revision:number;events:{id:number;project_id?:string;at?:string;kind?:string;title?:string}[]}>(`/events?after=${eventCursor.current}`),api<{jobs:Job[]}>('/jobs')]);if(!active)return;setJobs(j.jobs);setOnline(true);if(e.events.length){eventCursor.current=e.revision;setNewEvents(n=>n+e.events.length);const feedback=e.events.filter(event=>event.kind==='feedback_received'||event.kind==='feedback_corrected').at(-1);if(feedback?.title)notify(feedback.title);const latest=e.events.at(-1)?.at;if(latest)setLastSync(latest);const p=await api<{projects:Project[];scanned_at?:string}>('/projects');if(active)setProjects(p.projects);const current=workspaceRef.current.data;const primary=[current.activeProject,current.compareProject].filter(Boolean) as string[];for(const id of primary)await loadDetail(id);const touched=e.events.map(event=>event.project_id).filter((id):id is string=>Boolean(id&&catalogRef.current.details[id]));const extra=[...new Set([...readPanels(current).filter(panel=>panel.kind!=='process').map(panel=>panel.project_id),...touched])].filter(id=>!primary.includes(id)&&p.projects.some(project=>project.id===id));for(const id of extra){if(!active)break;try{await loadDetail(id);}catch(error){if(error instanceof ApiError&&error.status===401)throw error;}}}else eventCursor.current=e.revision;}catch(e){if(active){setOnline(false);if(e instanceof ApiError&&e.status===401)onError(e);}}finally{if(active)timer=setTimeout(poll,4000);}};timer=setTimeout(poll,1000);return()=>{active=false;clearTimeout(timer);};},[authenticated,ready,loadDetail,onError,notify]);
  useEffect(()=>{if(!ready||!authenticated)return;let alive=true;let timer:ReturnType<typeof setTimeout>;
    const poll=async()=>{try{const w=workspaceRef.current.data;const feed=await api<ReturnFeed>(`/returns?after=${Number(w.notificationReadId)||0}`);if(!alive)return;setReturnFeed(feed);setReturnError('');
      const cursor=typeof w.returnCursor==='number'?w.returnCursor:null;
      const arrivals=cursor===null?[]:feed.reports.filter(r=>r.sequence>cursor&&!r.historical&&r.renderable!==false).sort((a,b)=>a.sequence-b.sequence);
      if(arrivals.length){
        const homeReports=new Set(readPanels(workspaceRef.current.data).filter(p=>p.kind==='report').map(p=>`${p.project_id}:${p.ref}`));
        const responseArrivals=arrivals.filter(r=>!homeReports.has(reportKey(r)));
        if(responseArrivals.length){setPreviews(previous=>{const next=[...previous];for(const r of responseArrivals){const item={...r,caption:r.project_name};if(!next.some(p=>reportKey(p)===reportKey(item)))next.push(item);/* Keep each mounted report and its draft; ReportFrame offers the version switch. */}return next;});setResponsesVisible(true);}
        notify(`${arrivals.length} novo(s) retorno(s) na mesa.${arrivals.length>responseArrivals.length?' Relatórios já abertos continuam em seus painéis.':''}`);
      }
      if(cursor===null||feed.revision>cursor){updateWorkspace(current=>({...current,returnCursor:feed.revision,...(typeof current.notificationReadId!=='number'?{notificationReadId:feed.revision}:{})}));}
    }catch(e){if(alive){setReturnError('Não foi possível consultar os retornos');if(e instanceof ApiError&&e.status===401)onError(e);}}finally{if(alive)timer=setTimeout(poll,4000);}};
    void poll();return()=>{alive=false;clearTimeout(timer);};},[ready,authenticated,returnRefresh]);
  useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),6500);return()=>clearTimeout(t);},[toast]);
  useEffect(()=>{const handle=(e:KeyboardEvent)=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(authenticated)setSearch(s=>!s);}if(e.key==='Escape')setContext(null);};document.addEventListener('keydown',handle);return()=>document.removeEventListener('keydown',handle);},[authenticated]);
  useEffect(()=>{if(!context)return;const previous=document.activeElement as HTMLElement;const menu=document.querySelector<HTMLElement>('.context-menu');const items=Array.from(menu?.querySelectorAll<HTMLElement>('[role="menuitem"]')||[]);items[0]?.focus();const handler=(e:KeyboardEvent)=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const n=items.indexOf(document.activeElement as HTMLElement);items[(n+(e.key==='ArrowDown'?1:-1)+items.length)%items.length]?.focus();}if(e.key==='Tab'){e.preventDefault();setContext(null);}};menu?.addEventListener('keydown',handler);return()=>{menu?.removeEventListener('keydown',handler);previous?.focus();};},[context]);
  function updateWorkspace(fn:(w:Workspace)=>Workspace){editSerial.current++;setWorkspace(prev=>({...prev,data:fn(prev.data)}));setDirty(true);}
  useEffect(()=>{if(!dirty||!ready||savePaused||savingRef.current)return;const timer=setTimeout(async()=>{
    savingRef.current=true;setSaving(true);const serial=editSerial.current;const snapshot=workspaceRef.current;let data=snapshot.data;let revision=snapshot.revision;
    try{let next:Versioned<Workspace>;
      try{next=await api<Versioned<Workspace>>('/workspace','PUT',{revision,data});}
      catch(e){if(!(e instanceof ApiError)||e.status!==409)throw e;
        const remote=await api<Versioned<Workspace>>('/workspace');
        const merged=mergeWorkspace(savedBase.current,data,{...defaultWorkspace,...remote.data}) as Workspace|null;
        if(!merged||serial!==editSerial.current)throw e;
        data=merged;revision=remote.revision;
        next=await api<Versioned<Workspace>>('/workspace','PUT',{revision,data});
      }
      savedBase.current=data;
      if(serial===editSerial.current){setWorkspace(next);workspaceRef.current=next;setPreviews(Array.isArray(next.data.responseViews)?next.data.responseViews as Preview[]:[]);setResponsesVisible(next.data.responsesCollapsed!==true);setDirty(false);}
      else setWorkspace(prev=>({...prev,revision:next.revision}));
    }catch(e){setSavePaused(true);if(e instanceof ApiError&&e.status===409)setConflict(true);else onError(e);}finally{savingRef.current=false;setSaving(false);}
  },650);return()=>clearTimeout(timer);},[workspace,dirty,ready,savePaused,saving,onError]);

  useEffect(()=>{if(!ready)return;const present=async(event:Event)=>{const request=(event as CustomEvent).detail;try{const result=await api<{project_id:string;item:Preview|null}>('/present','POST',request);const shown=await showItem(result.project_id,result.item);(window as Window & {megabrainPresentationResult?:unknown}).megabrainPresentationResult=shown?{requestId:request.requestId,ok:true,project_id:result.project_id,title:result.item?.title}:{requestId:request.requestId,ok:false,project_id:result.project_id,error:'O item foi localizado, mas não apareceu na tela.'};}catch(e){(window as Window & {megabrainPresentationResult?:unknown}).megabrainPresentationResult={requestId:request.requestId,ok:false,error:(e as Error).message};onError(e);}};const openItem=(event:Event)=>{const result=(event as CustomEvent).detail;if(result?.item&&typeof result.project_id==='string')void showItem(result.project_id,result.item).catch(onError);}; (window as Window & {megabrainReady?:boolean}).megabrainReady=true;window.addEventListener('mb-open-item',openItem);window.addEventListener('mb-present',present);return()=>{(window as Window & {megabrainReady?:boolean}).megabrainReady=false;window.removeEventListener('mb-open-item',openItem);window.removeEventListener('mb-present',present);};},[ready]);
  async function reloadWorkspace(){try{const w=await api<Versioned<Workspace>>('/workspace');const {ws:data,overflow,invalid}=prepareWorkspace(w.data,catalogRef.current.projects,workspaceRef.current.data.view==='project'?'project':'home');setWorkspace({...w,data});workspaceRef.current={...w,data};savedBase.current=data;setResponsesVisible(data.responsesCollapsed!==true);setPreviews(Array.isArray(data.responseViews)?(data.responseViews as Preview[]).filter(p=>p&&typeof p.id==='string'&&typeof p.url==='string'&&typeof p.title==='string'&&safeUrl(p.url)):[]);setDirty(false);setSavePaused(false);setConflict(false);restoreNotice(overflow,invalid);notify('Mesa atualizada com a versão salva.');}catch(e){onError(e);}}
  function selectProject(id:string,compare=false){updateWorkspace(w=>({...w,openProjects:w.openProjects.includes(id)?w.openProjects:[...w.openProjects,id],...(compare?{compareProject:id===w.activeProject?null:id}:{activeProject:id,compareProject:w.compareProject===id?null:w.compareProject,view:'project' as const})}));setSearch(false);setComparePicker(false);}
  function closeProject(id:string){updateWorkspace(w=>{const open=w.openProjects.filter(p=>p!==id);return{...w,openProjects:open,activeProject:w.activeProject===id?open[0]||null:w.activeProject,compareProject:w.compareProject===id?null:w.compareProject};});}
  function goHome(){if(workspaceRef.current.data.view==='project')updateWorkspace(w=>({...w,view:'home'}));setResponsesVisible(false);setSearch(false);window.scrollTo({top:0});}
  function openDesk(id:string){selectProject(id);setResponsesVisible(false);window.scrollTo({top:0});}
  function revealExistingResponse(pid:string,fid:string):string|null{
    const existing=(Array.isArray(workspaceRef.current.data.responseViews)?workspaceRef.current.data.responseViews as Preview[]:[]).find(p=>p.project_id===pid&&p.id===fid);
    if(!existing)return null;
    const location=RESPONSE_LOCATION+reportKey(existing);setResponsesVisible(true);setSearch(false);focusPanel(location);return location;
  }
  /** Abre embaixo na home; o painel é montado a partir do catálogo carregado, nunca do que veio no arraste. */
  function openPanel(input:PanelInput,drop?:{x:number;y:number;cols:number},loaded?:ProjectDetail):string|null{
    if(input.kind==='report'&&input.ref){const existing=revealExistingResponse(input.project_id,input.ref);if(existing)return existing;}
    const {projects:list,jobs:jobList,details:cache}=catalogRef.current;
    const panel=resolvePanel(input,{projects:list,jobs:jobList,reports:pid=>{const d=loaded&&loaded.project.id===pid?loaded:cache[pid];return d?libraryItems(d):null;}});
    if(!panel){notify('Este item não está no catálogo carregado; nada foi aberto.');return null;}
    const status=addPanel(workspaceRef.current.data,panel,drop).status;
    if(status==='full'){notify(`A página principal já tem ${HOME_PANEL_LIMIT} painéis abertos. Feche um para abrir outro; nenhum foi retirado.`);return null;}
    if(status==='opened'||workspaceRef.current.data.view==='project')updateWorkspace(w=>{const result=addPanel(w,panel,drop);return {...(result.status==='opened'?result.ws:w),view:'home'};});
    setResponsesVisible(false);setSearch(false);focusPanel(panel.key);return panel.key;
  }
  function closePanel(key:string){updateWorkspace(w=>removePanel(w,key));}
  function openProject(id:string){if(homeView)openPanel({kind:'project',project_id:id});else selectProject(id);}
  function arrangeSideBySide(){updateWorkspace(w=>({...w,layouts:{...w.layouts,[homeLayoutKey(HOME_DESKTOP_COLS)]:[]}}));setTimeout(()=>document.getElementById('home-panels-title')?.scrollIntoView({behavior:'smooth',block:'start'}),60);}
  function openResponse(item:Preview){if(item.renderable===false){notify('Este relatório excede o limite de 64 MB do visualizador. A fonte precisa ser reduzida.');return;}setResponsesVisible(true);setPreviews(prev=>prev.some(p=>reportKey(p)===reportKey(item))?prev:[...prev,item]);}
  /** Na home, relatórios do catálogo abrem como painel ao lado dos demais; o resto segue para Respostas. */
  function openPreview(item:Preview,_compare=false){if(item.renderable===false){notify('Este relatório excede o limite de 64 MB do visualizador. A fonte precisa ser reduzida.');return;}if(item.project_id&&revealExistingResponse(item.project_id,item.id))return;if(workspaceRef.current.data.view!=='project'&&item.project_id){const d=catalogRef.current.details[item.project_id];if(d&&libraryItems(d).some(r=>r.id===item.id)&&openPanel({kind:'report',project_id:item.project_id,ref:item.id}))return;}openResponse(item);}
  async function showItem(pid:string,item:Preview|null):Promise<boolean>{
    if(workspaceRef.current.data.view!=='project'){
      if(!item){const key=openPanel({kind:'project',project_id:pid});return key?waitShown(panelReadySelector(key)):false;}
      const preview={...item,project_id:pid};let detail:ProjectDetail|undefined=catalogRef.current.details[pid];
      if(!detail||!libraryItems(detail).some(r=>r.id===preview.id)){try{detail=await loadDetail(pid);}catch(e){if(e instanceof ApiError&&e.status===401)throw e;}}
      if(detail&&libraryItems(detail).some(r=>r.id===preview.id)){const key=openPanel({kind:'report',project_id:pid,ref:preview.id},undefined,detail);if(key)return waitShown(panelReadySelector(key));}
      openResponse(preview);return waitShown(`[data-report-key="${CSS.escape(reportKey(preview))}"]`);
    }
    selectProject(pid);
    if(!item)return waitShown(`[data-cf-project="${CSS.escape(pid)}"]`);
    const preview={...item,project_id:pid};openResponse(preview);return waitShown(`[data-report-key="${CSS.escape(reportKey(preview))}"]`);
  }
  function closePreview(key?:string){if(!key){setResponsesVisible(false);return;}setPreviews(prev=>prev.filter(p=>reportKey(p)!==key));}
  useEffect(()=>{if(ready&&ws.responsesCollapsed!==!responsesVisible)updateWorkspace(w=>({...w,responsesCollapsed:!responsesVisible}));},[responsesVisible,ready]);
  useEffect(()=>{if(ready&&JSON.stringify(ws.responseViews||[])!==JSON.stringify(previews))updateWorkspace(w=>({...w,responseViews:previews}));},[previews,ready]);
  async function loadGuide(){setGuideOpen(true);try{setGuide(await api<Guide>('/guide'));}catch(e){onError(e);}}
  async function loadConnection(){setConnectionOpen(true);setConnection(null);try{setConnection(await api('/connection'));}catch(e){onError(e);}}
  function beginComment(ctx:Context){setComment(ctx);setCommentText(commentDrafts.current[ctx.pid+':'+ctx.target]||'');}
  async function postComment(){if(!comment||!commentText.trim()||commentBusy)return;setCommentBusy(true);try{const payload={text:commentText.trim(),target:comment.target,anchor:comment.anchor};await api(`/projects/${comment.pid}/comments`,'POST',payload,mutationKey(commentRequest,{pid:comment.pid,...payload}));commentRequest.current=null;delete commentDrafts.current[comment.pid+':'+comment.target];setCommentText('');notify('Comentário salvo no projeto.');void loadDetail(comment.pid).catch(onError);}catch(e){onError(e);}finally{setCommentBusy(false);}}
  async function addReference(){if(!referenceProject||referenceBusy)return;const url=safeUrl(referenceUrl);if(!url||!/^https?:\/\//i.test(referenceUrl)){notify('Informe um endereço completo começando por https://.');return;}setReferenceBusy(true);try{const payload={url,title:referenceTitle.trim()||new URL(url).hostname};await api(`/projects/${referenceProject}/references`,'POST',payload,mutationKey(referenceRequest,{pid:referenceProject,...payload}));referenceRequest.current=null;void loadDetail(referenceProject).catch(onError);setReferenceProject(null);setReferenceUrl('');setReferenceTitle('');notify('Referência adicionada.');}catch(e){onError(e);}finally{setReferenceBusy(false);}}
  async function cancelJob(id:string){try{const result=await api<{job:Job}>(`/jobs/${encodeURIComponent(id)}/cancel`,'POST',{});setJobs(previous=>previous.map(job=>job.id===id?result.job:job));notify('Interrupção solicitada. O estado será atualizado em Atividade.');}catch(e){onError(e);}}
  async function copy(value:string){try{await navigator.clipboard.writeText(value);notify('Copiado.');}catch{notify('A cópia automática não está disponível. Selecione o texto e copie.');}}
  const active=projects.find(p=>p.id===ws.activeProject);const comparison=projects.find(p=>p.id===ws.compareProject);const activeJobs=jobs.filter(j=>isRunning(j.status));
  function boardFor(detail:ProjectDetail,compare=false){const pid=detail.project.id;return <ProjectBoard detail={detail} jobs={jobs} ws={ws} updateWorkspace={updateWorkspace} openPreview={(item,c)=>openPreview({...item,project_id:pid},c)} onContext={setContext} onError={onError} onSaved={notify} onReload={()=>void loadDetail(pid).catch(onError)} onStartJob={()=>setJobProject(pid)} onCancelJob={cancelJob} onReference={()=>{setReferenceProject(pid);setReferenceUrl('');setReferenceTitle('');}} compare={compare}/>;}
  const homePanelProjects=new Set(readPanels(ws).filter(p=>p.kind==='project').map(p=>p.project_id));
  function showProcess(){if(!active){setSearch(true);return;}if(homeView)selectProject(active.id);if(active){updateWorkspace(w=>({...w,hiddenModules:{...w.hiddenModules,[active.id]:(w.hiddenModules[active.id]||[]).filter(id=>id!=='process')}}));setResponsesVisible(false);setTimeout(()=>document.getElementById(`${active.id}-process`)?.scrollIntoView({behavior:'smooth',block:'start'}),100);}}
  const quickActions=[{id:'quotas',label:'Cotas de IA',description:'Uso, janelas e origem dos dados',icon:Activity,onClick:()=>setQuotasOpen(true)},{id:'process',label:'Processo do projeto',description:'Etapas e responsáveis deste projeto',icon:Workflow,onClick:showProcess},{id:'phone',label:'Levar no celular',description:'Conexão com seu computador',icon:Smartphone,onClick:()=>void loadConnection()},{id:'settings',label:'Configurações',description:'Aparência, cotas e atalhos',icon:Settings2,onClick:()=>setSettingsOpen(true)}];
  const filteredActions=quickActions.filter(a=>`${a.label} ${a.description}`.toLocaleLowerCase().includes(query.toLocaleLowerCase()));
  const filtered=projects.filter(p=>`${p.name} ${p.summary||''}`.toLowerCase().includes(query.toLowerCase()));
  if(authenticated===null)return <div className="boot-screen"><img src={brain} alt=""/><LoaderCircle className="spin" size={22}/><p>Abrindo sua mesa…</p></div>;
  if(!authenticated)return <Login onConnected={()=>{initialized.current=false;setAuthenticated(true);}}/>;
  return <div className={`app-shell flexible-shell ${homeView?'home-visible':''} dock-${prefs.position} rail-${prefs.mode} ${sidebar?'':'rail-collapsed'}`} style={{'--space-factor':prefs.spacing/100,...(prefs.mode==='expanded'?{'--user-rail-size':`${typeof ws.railWidth==='number'?Math.max(170,Math.min(480,ws.railWidth)):220}px`}:{})} as CSSProperties}><CursorTools projectKey={ready&&authenticated?(homeView?'home':ws.activeProject?`${ws.activeProject}:${ws.compareProject||''}`:null):null} onSaved={notify} onError={onError} onReload={pid=>void loadDetail(pid).catch(onError)}/><a className="skip-link" href="#workspace">Pular para a mesa</a><aside className={`project-rail ${sidebar?'is-open':''}`}><ProjectRailHandle ws={ws} update={updateWorkspace}/><a className="brand" href="#workspace" aria-label="Página principal do MegaBrain" onClick={e=>{e.preventDefault();goHome();}}><img src={brain} alt=""/><span>megabrain<span className="brand-dot">.</span><small>seu espaço de trabalho</small></span></a><button className="rail-search" onClick={()=>setSearch(true)}><Search size={17}/><span>Buscar na mesa</span><kbd>Ctrl K</kbd></button><div className="rail-label"><span>SEUS PROJETOS</span><span>{projects.length||''}</span></div><nav aria-label="Projetos">{projects.map(p=>{const current=!homeView&&active?.id===p.id;const below=homeView&&homePanelProjects.has(p.id);return <button className={`project-link ${current?'active':''} ${below?'in-home':''}`} key={p.id} title={homeView?`${p.name} · clique ou arraste para abrir embaixo`:p.name} aria-label={homeView?`${p.name}: abrir embaixo na página principal`:p.name} aria-current={current?'page':undefined} draggable={homeView} onDragStart={homeView?e=>{e.dataTransfer.setData(DRAG_PANEL,JSON.stringify({kind:'project',project_id:p.id}));e.dataTransfer.effectAllowed='copy';}:undefined} onClick={()=>openProject(p.id)}><span className="project-monogram" style={{'--project-color':p.color||'#ff82c4'} as CSSProperties}>{initial(p.name)}</span><span className="project-link-name">{p.name}<small>{p.summary||'Abrir projeto'}</small></span>{current&&<span className="active-pip"/>}{below&&<span className="home-pip" aria-hidden="true"/>}</button>;})}</nav><div className="rail-bottom"><button className="rail-action" onClick={()=>void loadGuide()}><BookOpen size={18}/><span>Guia do MegaBrain<small>Tutorial de uso e funções</small></span><ArrowUpRight size={15}/></button><button className="rail-action" onClick={()=>void loadConnection()}><Smartphone size={18}/><span>Levar no celular<small>Sua mesa fora de casa</small></span><ArrowUpRight size={15}/></button><div className="rail-owner"><span className="avatar">H</span><span>Usuário<small>Meu MegaBrain</small></span><span className={`connection-dot ${online?'':'offline'}`}/></div></div></aside>{sidebar&&<button className="rail-overlay" aria-label="Fechar projetos" onClick={()=>setSidebar(false)}/>}
    <div className="main-shell"><header className="topbar"><div className="topbar-left"><IconButton icon={sidebar?PanelLeftClose:PanelLeftOpen} label={sidebar?'Ocultar projetos':'Mostrar projetos'} onClick={()=>setSidebar(!sidebar)}/><nav className="breadcrumb" aria-label="Onde você está"><button className="breadcrumb-home" aria-current={homeView?'page':undefined} title="Ir para a página principal" onClick={goHome}><LayoutDashboard size={14}/>Meu espaço</button><ChevronRight size={14} aria-hidden="true"/><strong>{homeView?'Página principal':active?.name||'Projetos'}</strong></nav></div><div className="topbar-actions"><Notifications feed={returnFeed} readId={Number(ws.notificationReadId)||0} projects={projects} onRead={()=>{updateWorkspace(w=>({...w,notificationReadId:returnFeed?.revision||0}));setReturnFeed(f=>f?{...f,unread:0}:f);setReturnRefresh(n=>n+1);}} onOpen={openPreview} onProject={selectProject}/>{previews.length>0&&<button className="secondary" onClick={()=>setResponsesVisible(!responsesVisible)}><Columns2 size={16}/>Respostas ({previews.length})</button>}<button className="secondary quotas-top-button" onClick={()=>setQuotasOpen(true)}><Activity size={17}/>Cotas de IA</button><QuickAccess actions={quickActions.filter(a=>a.id!=='settings')} onSettings={()=>setSettingsOpen(true)}/><WorkspacePreferences ws={ws} update={updateWorkspace}/><span className={`connection-state ${online?'':'disconnected'}`} title={lastSync?`Última atualização da fonte: ${dateText(lastSync)}`:'Conexão com a central'}>{online?<Wifi size={14}/>:<WifiOff size={14}/>}<span>{online?'Conectado':'Reconectando'}</span></span><IconButton icon={Search} label="Buscar · Ctrl ou Cmd K" onClick={()=>setSearch(true)}/><IconButton icon={Smartphone} label="Conexão com celular" onClick={()=>void loadConnection()}/></div></header>
      <main id="workspace" className={previews.length>0&&responsesVisible?'reading-mode':undefined}>{homeView?<section className="desk-bar" aria-label="Minha mesa"><div className="desk-bar-title"><h1>Minha mesa</h1><small>{readPanels(ws).length} de {HOME_PANEL_LIMIT} abertos embaixo · clique ou arraste para abrir</small></div><div className="desk-bar-actions"><button className="secondary" aria-label="Lado a lado: organizar os abertos dois por linha" title="Organizar os abertos dois por linha" onClick={arrangeSideBySide} disabled={readPanels(ws).length<2}><Columns2 size={16}/><span className="desk-bar-label">Lado a lado</span></button><button className="primary" aria-label="Novo pedido" onClick={()=>setJobPicker(true)} disabled={!projects.length}><Plus size={16}/><span className="desk-bar-label">Novo pedido</span></button></div></section>
      :<section className="desk-bar" aria-label="Projeto ativo"><div className="desk-bar-title"><IconButton icon={ArrowLeft} label="Voltar à página principal" onClick={goHome}/>{active&&<span className="project-swatch" style={{background:active.color||'#ff82c4'}}/>}<h1>{active?.name||'Escolha um projeto'}</h1><small>{active?'Projeto ativo':'Nenhum projeto aberto'}{comparison?` · ao lado: ${comparison.name}`:''}</small></div><div className="desk-bar-actions"><button className="secondary" aria-label="Lado a lado: escolher outro projeto" onClick={()=>setComparePicker(true)} disabled={!active||projects.length<2}><Columns2 size={16}/><span className="desk-bar-label">Lado a lado</span></button><button className="primary" aria-label="Novo pedido" onClick={()=>active&&setJobProject(active.id)} disabled={!active}><Plus size={16}/><span className="desk-bar-label">Novo pedido</span></button></div></section>}
      <div className="workspace-status"><div>{activeJobs.length>0?<span><LoaderCircle size={14} className="spin"/>{activeJobs.length} pedido{activeJobs.length===1?'':'s'} em andamento</span>:<span><ShieldCheck size={14}/>Seu espaço privado</span>}<span title="Relatórios HTML nas raízes conectadas, incluindo histórico.">{projects.reduce((n,p)=>n+(p.report_count||0),0)} relatórios · {projects.length} projetos</span>{newEvents>0&&<button className="update-badge" onClick={()=>{setNewEvents(0);const target=homeView?document.getElementById('home-process-title'):active?document.getElementById(`${active.id}-activity`):null;target?.scrollIntoView({behavior:'smooth',block:'nearest'});}}><Activity size={13}/>{newEvents} {newEvents===1?'atualização':'atualizações'}<ArrowDown size={12}/></button>}</div><button className={`save-state ${savePaused?'warning':''}`} onClick={()=>{if(savePaused)setConflict(true);}} disabled={!savePaused}>{saving?<LoaderCircle className="spin" size={13}/>:savePaused?<CircleAlert size={13}/>:<CheckCheck size={13}/>} {saving?'Salvando mesa…':savePaused?'Rascunho sem salvar':dirty?'Alterações por salvar':'Mesa salva'}</button></div>
      {!homeView&&comparison&&<label className="comparison-size-control">Divisão entre os projetos<input type="range" min="20" max="80" aria-label="Espaço do projeto à esquerda" value={typeof ws.compareRatio==='number'?ws.compareRatio:50} onChange={e=>updateWorkspace(w=>({...w,compareRatio:Number(e.target.value)}))}/><span>{typeof ws.compareRatio==='number'?ws.compareRatio:50}% à esquerda</span></label>}
      {!homeView&&<><SessionConnections onProject={id=>selectProject(id)}/><div className="project-tabs" role="tablist" aria-label="Projetos abertos">{ws.openProjects.map(id=>{const p=projects.find(p=>p.id===id);return p?<div className={`project-tab ${ws.activeProject===id?'selected':''}`} key={id}><button role="tab" aria-selected={ws.activeProject===id} onClick={()=>selectProject(id)}><Folder size={15}/>{p.name}{ws.compareProject===id&&<Columns2 size={13}/>}</button><IconButton icon={Pin} label={ws.compareProject===id?`Desafixar ${p.name}`:`Fixar ${p.name} ao lado`} disabled={ws.activeProject===id} className={ws.compareProject===id?'pinned':''} onClick={()=>updateWorkspace(w=>({...w,compareProject:w.compareProject===id?null:id}))}/><IconButton icon={X} label={`Fechar aba ${p.name}`} onClick={()=>closeProject(id)}/></div>:null;})}<IconButton icon={Plus} label="Abrir projeto" onClick={()=>setSearch(true)}/></div></>}
      {homeView&&ready&&<HomeDesk projects={projects} details={details} jobs={jobs} online={online} ws={ws} update={updateWorkspace} loadDetail={loadDetail} onError={onError} onSaved={notify} onOpen={(input,drop)=>{openPanel(input,drop);}} onClose={closePanel} onOpenDesk={openDesk} onCancelJob={cancelJob} onPreview={item=>openPreview(item)} renderProject={detail=>boardFor(detail)} renderPreview={item=><PreviewContent item={item}/>}/>}
      <ReturnInbox feed={returnFeed} error={returnError} openCount={previews.length} visible={responsesVisible} onToggle={()=>setResponsesVisible(!responsesVisible)} onOpen={openPreview} onRefresh={()=>setReturnRefresh(n=>n+1)}/>
      {previews.length>0&&responsesVisible?<MultiReportWorkspace items={previews} ws={ws} update={updateWorkspace} onClose={closePreview} onAdd={()=>setPreviewPicker(true)} render={p=><PreviewContent key={reportKey(p)+':'+(p.hash||'')} item={p}/>}/>:null}
      {<>{!ready?<div className="initial-loading">{loadError?<><CircleAlert size={24}/><p>{loadError}</p><button className="secondary" onClick={()=>void boot()}>Tentar novamente</button></>:<><LoaderCircle className="spin" size={22}/><p>Lendo seus projetos…</p></>}</div>:homeView?null:active?<><div className={`boards ${comparison?'boards-double':''}`} style={comparison?{gridTemplateColumns:`minmax(0,${typeof ws.compareRatio==='number'?ws.compareRatio:50}fr) minmax(0,${100-(typeof ws.compareRatio==='number'?ws.compareRatio:50)}fr)`}:undefined}>{[active,comparison].filter(Boolean).map((p,i)=><div className="board-group" key={p!.id}>{i===1&&<button className="close-comparison text-button" onClick={()=>updateWorkspace(w=>({...w,compareProject:null}))}><X size={14}/>Fechar comparação</button>}{details[p!.id]?boardFor(details[p!.id],i===1):<div className="initial-loading"><LoaderCircle className="spin" size={20}/><p>Lendo o contexto do projeto…</p></div>}</div>)}</div></>:<Empty icon={Folder} title="Escolha um projeto para colocar na mesa"><button className="text-button" onClick={()=>setSearch(true)}>Abrir meus projetos <ArrowRight size={15}/></button></Empty>}</>}
      {homeView&&<SessionConnections onProject={openProject}/>}
      <footer className="workspace-footer"><span><MessageCircle size={13}/>Segure por 1 segundo para comentar. Ou use o menu de cada módulo.</span><button className="text-button" onClick={()=>void loadGuide()}>Guia do MegaBrain <ArrowUpRight size={13}/></button></footer></main></div>
    {quotasOpen&&<Modal title="Cotas de IA" onClose={()=>setQuotasOpen(false)} wide><QuotasPanel onError={onError} onSaved={notify}/></Modal>}
    {settingsOpen&&<Modal title="Configurações da central" onClose={()=>setSettingsOpen(false)}><p className="modal-intro">Escolha o assunto. As mudanças de aparência são reversíveis.</p><WorkspacePreferences ws={ws} update={updateWorkspace}/><fieldset className="start-view"><legend>Ao abrir o MegaBrain</legend><div className="start-view-options">{([['home','Página principal'],['last','Onde parei']] as const).map(([value,label])=><button key={value} className="secondary" aria-pressed={(ws.startView==='last'?'last':'home')===value} onClick={()=>updateWorkspace(w=>({...w,startView:value}))}>{label}</button>)}</div></fieldset><div className="search-results">{quickActions.filter(a=>a.id!=='settings').map(a=><button key={a.id} onClick={()=>{setSettingsOpen(false);a.onClick();}}><a.icon size={20}/><span><strong>{a.label}</strong><small>{a.description}</small></span><ArrowRight size={17}/></button>)}</div></Modal>}
    {toast&&<div className="toast" role="status"><CircleAlert size={17}/><span>{toast}</span><IconButton icon={X} label="Fechar aviso" onClick={()=>setToast('')}/></div>}
    {context&&<><button className="context-dismiss" aria-label="Fechar ferramentas" onClick={()=>setContext(null)}/><div role="menu" aria-label={`Ferramentas de ${context.label}`} className="context-menu" style={{left:Math.max(12,Math.min(context.x,window.innerWidth-276)),top:Math.max(12,Math.min(context.y,window.innerHeight-190))}}><span className="eyebrow">FERRAMENTAS DA MESA</span><strong>{context.label}</strong><button role="menuitem" onClick={()=>{beginComment(context);setContext(null);}}><MessageCircle size={18}/><span>Comentar aqui<small>Fica salvo neste projeto</small></span><ArrowRight size={15}/></button><button role="menuitem" onClick={()=>{beginComment(context);setContext(null);}}><BookOpen size={17}/>Ver comentários</button></div></>}
    {search&&<Modal title="O que você quer abrir?" onClose={()=>{setSearch(false);setQuery('');}}><div className="search-field"><Search size={21}/><input aria-label="Buscar projeto" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Busque projeto, cota ou configuração…" autoFocus/></div><div className="search-results">{filteredActions.map(a=><button key={a.id} onClick={()=>{setSearch(false);a.onClick();}}><a.icon size={20}/><span><strong>{a.label}</strong><small>{a.description}</small></span><ArrowRight size={17}/></button>)}{filtered.map(p=><button key={p.id} onClick={()=>openProject(p.id)}><span className="project-monogram" style={{'--project-color':p.color||'#ff82c4'} as CSSProperties}>{initial(p.name)}</span><span><strong>{p.name}</strong><small>{p.summary||'Abrir na mesa'}</small></span><ArrowRight size={17}/></button>)}{filtered.length===0&&filteredActions.length===0&&<Empty icon={Search} title="Nenhum projeto encontrado">Tente outra palavra.</Empty>}</div></Modal>}
    {comparePicker&&<Modal title="O que fica ao lado?" onClose={()=>setComparePicker(false)}><p className="modal-intro">Mantenha {active?.name} à esquerda e abra outro projeto à direita. No celular, os grupos ficam em sequência.</p><div className="search-results">{projects.filter(p=>p.id!==active?.id).map(p=><button key={p.id} onClick={()=>selectProject(p.id,true)}><Folder size={20}/><span><strong>{p.name}</strong><small>{p.summary}</small></span><Columns2 size={18}/></button>)}</div></Modal>}
    {comment&&<Modal title={`Comentar · ${comment.label}`} onClose={()=>setComment(null)}><p className="modal-intro">Seu comentário fica ligado a esta área de {projects.find(p=>p.id===comment.pid)?.name}.</p><label htmlFor="comment-text">O que você quer registrar?</label><textarea id="comment-text" rows={4} value={commentText} onChange={e=>{setCommentText(e.target.value);commentDrafts.current[comment.pid+':'+comment.target]=e.target.value;}} placeholder="Anote uma observação, ajuste ou decisão…"/><div className="modal-actions"><span className="fine-print"><ShieldCheck size={14}/>O comentário ficará neste projeto</span><button className="primary" disabled={!commentText.trim()||commentBusy} onClick={()=>void postComment()}>{commentBusy?<LoaderCircle className="spin" size={16}/>:<Send size={16}/>}Salvar comentário</button></div><div className="comment-history">{(details[comment.pid]?.comments||[]).filter(c=>c.target===comment.target).map(c=><article key={c.id}><span className="avatar small">H</span><div><strong>Usuário <small>{dateText(c.at)}</small></strong><p>{c.text}</p><span className="proof-label verified"><Check size={12}/>Salvo</span></div></article>)}</div></Modal>}
    {referenceProject&&<Modal title="Adicionar uma referência" onClose={()=>setReferenceProject(null)}><p className="modal-intro">Guarde a fonte junto do projeto para comparar depois.</p><form onSubmit={e=>{e.preventDefault();void addReference();}}><label htmlFor="ref-title">Nome da referência</label><input id="ref-title" value={referenceTitle} onChange={e=>setReferenceTitle(e.target.value)} placeholder="Ex.: direção visual, artigo, arquivo do Figma"/><label htmlFor="ref-url">Endereço</label><input id="ref-url" type="url" value={referenceUrl} onChange={e=>setReferenceUrl(e.target.value)} placeholder="https://…" required/><div className="modal-actions"><button className="secondary" type="button" onClick={()=>setReferenceProject(null)}>Cancelar</button><button className="primary" disabled={!referenceUrl||referenceBusy}>{referenceBusy?<LoaderCircle className="spin" size={16}/>:<Plus size={16}/>}Adicionar à mesa</button></div></form></Modal>}
    {jobPicker&&<Modal title="Novo pedido para qual projeto?" onClose={()=>setJobPicker(false)}><div className="search-results">{projects.map(p=><button key={p.id} onClick={()=>{setJobPicker(false);setJobProject(p.id);}}><span className="project-monogram" style={{'--project-color':p.color||'#ff82c4'} as CSSProperties}>{initial(p.name)}</span><span><strong>{p.name}</strong><small>{p.summary||'Começar um pedido neste projeto'}</small></span><ArrowRight size={17}/></button>)}</div></Modal>}
    {jobProject&&<Modal title="Começar um pedido" onClose={()=>setJobProject(null)}><AnalysisForm pid={jobProject} projectName={projects.find(p=>p.id===jobProject)?.name||'este projeto'} onClose={()=>setJobProject(null)} onError={onError} onStarted={job=>{setJobs(prev=>[job,...prev.filter(j=>j.id!==job.id)]);setJobProject(null);notify('Pedido criado. Acompanhe a execução em Atividade.');}}/></Modal>}

    {previewPicker&&<Modal title="Adicionar resposta ou referência" onClose={()=>setPreviewPicker(false)}><p className="modal-intro">Escolha um retorno de qualquer projeto ou uma referência dos projetos abertos.</p><div className="search-results">{(returnFeed?.reports||[]).map(p=><button key={p.key} onClick={()=>{openPreview({...p,caption:p.project_name});setPreviewPicker(false);}}><FileImage size={22}/><span><strong>{p.title}</strong><small>{p.project_name}</small></span><Columns2 size={17}/></button>)}{[ws.activeProject,ws.compareProject].filter(Boolean).flatMap(id=>{const d=details[id!];if(!d)return[];return [...d.deliveries.filter(f=>f.file_id).map(f=>({id:f.file_id!,title:f.title,type:f.type||'html',url:fileUrl(f.file_id!),caption:d.project.name,project_id:d.project.id})),...[...(d.assets||[]),...(d.references||[])].map(f=>({id:f.id,title:f.name||f.title||'Referência',type:f.type||'link',url:f.url||fileUrl(f.id),caption:d.project.name,project_id:d.project.id}))];}).map((p,i)=><button key={`${p.id}-${i}`} onClick={()=>{openPreview(p,true);setPreviewPicker(false);}}><FileImage size={22}/><span><strong>{p.title}</strong><small>{p.caption}</small></span><Columns2 size={17}/></button>)}</div></Modal>}
    {conflict&&<Modal title="Sua mesa mudou em outro lugar" onClose={()=>setConflict(false)}><div className="analysis-callout"><CircleAlert size={23}/><p>O layout local ainda está aqui. Recarregue para usar a versão salva em outro dispositivo, ou mantenha este rascunho sem sobrescrever aquela versão.</p></div><div className="modal-actions"><button className="secondary" onClick={()=>setConflict(false)}>Manter rascunho</button><button className="primary" onClick={()=>void reloadWorkspace()}><RefreshCw size={16}/>Recarregar mesa</button></div></Modal>}
    {guideOpen&&<Modal title="Guia do MegaBrain" onClose={()=>setGuideOpen(false)} wide>{guide?<div className="guide-content">{guide.sections.map((s,i)=><section key={s.id}><span className="guide-number">{String(i+1).padStart(2,'0')}</span><div><h3>{s.title}</h3><p>{s.summary}</p>{s.url&&safeUrl(s.url)&&<a className="text-button" href={safeUrl(s.url)!} target="_blank" rel="noreferrer">Abrir editável no Figma <ExternalLink size={15}/></a>}{s.image&&safeUrl(s.image)&&<img src={safeUrl(s.image)!} alt={`Esquema de ${s.title}`}/>}<details><summary>Ver detalhes <ChevronDown size={15}/></summary><ul>{s.items.map((item,n)=><li key={n}><Check size={15}/>{item}</li>)}</ul></details></div></section>)}<section><div><h3>Fontes e editáveis</h3>{guide.sources.map((s,i)=><p key={i}><a className="text-button" href={safeUrl(s.url)||undefined} target="_blank" rel="noreferrer">{s.title} <ExternalLink size={14}/></a></p>)}</div></section></div>:<div className="loading-line"><LoaderCircle className="spin" size={17}/>Abrindo tutorial…</div>}</Modal>}
    {connectionOpen&&<Modal title="Sua mesa fora de casa" onClose={()=>setConnectionOpen(false)}><div className="connection-art"><Smartphone size={42}/><span className="connection-path"/><img src={brain} alt=""/></div>{connection?<><span className="small-tag">{connection.platform||'Celular'}</span><h3 className="connection-title">{connection.status}</h3>{connection.computer_required&&<p className="modal-intro">O computador precisa estar ligado para acessar os arquivos locais e executar análises.</p>}{connection.pair_url?<><label>Link privado para conectar este dispositivo</label><div className="copy-field"><input readOnly value={connection.pair_url} aria-label="Link privado de conexão"/><IconButton icon={Copy} label="Copiar link privado" onClick={()=>void copy(connection.pair_url!)}/></div>{connection.qr_url&&safeUrl(connection.qr_url)&&<img className="connection-qr" src={safeUrl(connection.qr_url)!} alt="QR Code privado para conectar o celular"/>}<p className="fine-print">Use somente nos seus dispositivos. O código é removido do endereço após conectar.</p></>:<div className="analysis-callout"><Unplug size={23}/><p>A conexão externa ainda não está disponível. O acesso local continua funcionando.</p></div>}{connection.remote_url&&safeUrl(connection.remote_url)&&<a className="secondary" href={safeUrl(connection.remote_url)!} target="_blank" rel="noopener noreferrer">Abrir endereço da central <SquareArrowOutUpRight size={15}/></a>}</>:<div className="loading-line"><LoaderCircle className="spin" size={17}/>Verificando conexão…</div>}</Modal>}
  </div>;
}
